create table if not exists tenants (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  name text not null,\n  category text,\n  unit text,\n  rent_rate_pct numeric,\n  created_at timestamptz not null default now()\n);\nalter table tenants enable row level security;\ndrop policy if exists "tenants_v1_read" on tenants;\ncreate policy "tenants_v1_read" on tenants for select using (true);\ndrop policy if exists "tenants_v1_write" on tenants;\ncreate policy "tenants_v1_write" on tenants for all using (true) with check (true);\n\ncreate table if not exists sales_records (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  tenant_id uuid not null,\n  period_type text not null check (period_type in ('hourly','daily','weekly','monthly')),\n  amount numeric not null check (amount >= 0),\n  recorded_at timestamptz not null default now(),\n  source text default 'manual',\n  created_at timestamptz not null default now()\n);\nalter table sales_records enable row level security;\ndrop policy if exists "sales_records_v1_read" on sales_records;\ncreate policy "sales_records_v1_read" on sales_records for select using (true);\ndrop policy if exists "sales_records_v1_write" on sales_records;\ncreate policy "sales_records_v1_write" on sales_records for all using (true) with check (true);\n\ncreate table if not exists projections (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  tenant_id uuid not null,\n  target_period text not null check (target_period in ('weekly','monthly')),\n  projected_amount numeric not null,\n  method text default 'trailing_avg_7d',\n  confidence numeric check (confidence >= 0 and confidence <= 1),\n  source text default 'rule_based',\n  review_status text default 'unreviewed',\n  created_at timestamptz not null default now()\n);\nalter table projections enable row level security;\ndrop policy if exists "projections_v1_read" on projections;\ncreate policy "projections_v1_read" on projections for select using (true);\ndrop policy if exists "projections_v1_write" on projections;\ncreate policy "projections_v1_write" on projections for all using (true) with check (true);\n\ninsert into tenants (name, category, unit, rent_rate_pct) values\n  ('Coffee House', 'F&B', 'A-12', 8.0),\n  ('Urban Fashion', 'Fashion', 'B-05', 6.5),\n  ('Tech World', 'Electronics', 'C-03', 5.0),\n  ('Green Grocer', 'Grocery', 'A-08', 4.5),\n  ('PlayZone Toys', 'Kids', 'D-10', 7.0)\non conflict do nothing;\n\ninsert into sales_records (tenant_id, period_type, amount, recorded_at, source)\nselect t.id, 'daily', 3200, (now() - interval '6 days')::date, 'manual' from tenants t where t.name = 'Coffee House'\nunion all select t.id, 'daily', 2850, (now() - interval '5 days')::date, 'manual' from tenants t where t.name = 'Coffee House'\nunion all select t.id, 'daily', 3400, (now() - interval '4 days')::date, 'manual' from tenants t where t.name = 'Coffee House'\nunion all select t.id, 'daily', 3100, (now() - interval '3 days')::date, 'manual' from tenants t where t.name = 'Coffee House'\nunion all select t.id, 'daily', 3600, (now() - interval '2 days')::date, 'manual' from tenants t where t.name = 'Coffee House'\nunion all select t.id, 'daily', 3250, (now() - interval '1 days')::date, 'manual' from tenants t where t.name = 'Coffee House'\nunion all select t.id, 'daily', 3900, now()::date, 'manual' from tenants t where t.name = 'Coffee House'\nunion all select t.id, 'daily', 5100, (now() - interval '6 days')::date, 'manual' from tenants t where t.name = 'Urban Fashion'\nunion all select t.id, 'daily', 4800, (now() - interval '5 days')::date, 'manual' from tenants t where t.name = 'Urban Fashion'\nunion all select t.id, 'daily', 5300, (now() - interval '4 days')::date, 'manual' from tenants t where t.name = 'Urban Fashion'\nunion all select t.id, 'daily', 4900, (now() - interval '3 days')::date, 'manual' from tenants t where t.name = 'Urban Fashion'\nunion all select t.id, 'daily', 5600, (now() - interval '2 days')::date, 'manual' from tenants t where t.name = 'Urban Fashion'\nunion all select t.id, 'daily', 5200, (now() - interval '1 days')::date, 'manual' from tenants t where t.name = 'Urban Fashion'\nunion all select t.id, 'daily', 5800, now()::date, 'manual' from tenants t where t.name = 'Urban Fashion'\nunion all select t.id, 'daily', 8200, (now() - interval '6 days')::date, 'manual' from tenants t where t.name = 'Tech World'\nunion all select t.id, 'daily', 7900, (now() - interval '5 days')::date, 'manual' from tenants t where t.name = 'Tech World'\nunion all select t.id, 'daily', 8500, (now() - interval '4 days')::date, 'manual' from tenants t where t.name = 'Tech World'\nunion all select t.id, 'daily', 8100, (now() - interval '3 days')::date, 'manual' from tenants t where t.name = 'Tech World'\nunion all select t.id, 'daily', 8800, (now() - interval '2 days')::date, 'manual' from tenants t where t.name = 'Tech World'\nunion all select t.id, 'daily', 8400, (now() - interval '1 days')::date, 'manual' from tenants t where t.name = 'Tech World'\nunion all select t.id, 'daily', 9000, now()::date, 'manual' from tenants t where t.name = 'Tech World';\n\ninsert into projections (tenant_id, target_period, projected_amount, method, confidence, source, review_status)\nselect t.id, 'weekly', 3285.71, 'trailing_avg_7d', 0.7, 'rule_based', 'unreviewed' from tenants t where t.name = 'Coffee House'\nunion all select t.id, 'weekly', 5100.00, 'trailing_avg_7d', 0.7, 'rule_based', 'unreviewed' from tenants t where t.name = 'Urban Fashion'\nunion all select t.id, 'weekly', 8400.00, 'trailing_avg_7d', 0.7, 'rule_based', 'unreviewed' from tenants t where t.name = 'Tech World'\non conflict do nothing;